sp_widget.client_script:
api.controller = function($window, $timeout, $document) {
  var c = this;
  var HIDE = ['Home', 'Reserve a Car', 'My Reservations', 'File a Complaint', 'Tours'];
  function hideNow() {
    var links = $document[0].querySelectorAll('header a, .navbar a, nav a, .sp-nav a, .sp-header a');
    var hits = 0;
    for (var i = 0; i < links.length; i++) {
      var txt = (links[i].textContent || '').replace(/\s+/g, ' ').trim();
      for (var j = 0; j < HIDE.length; j++) {
        if (txt === HIDE[j]) {
          var el = links[i];
          while (el && el.tagName !== 'LI' && el.tagName !== 'UL' && el !== $document[0].body) el = el.parentNode;
          (el && el.tagName === 'LI' ? el : links[i]).style.display = 'none';
          hits++;
          break;
        }
      }
    }
    return hits;
  }
  if (!c.data.staff) return;
  var tries = 0;
  var timer = $window ? null : null;
  var iv = setInterval(function() {
    hideNow();
    if (++tries > 12) clearInterval(iv);
  }, 400);
  $timeout(hideNow, 0);
};

sp_widget.script:
(function() {
  data.staff = false;
  data.links = [];
  var u = gs.getUser();
  try {
    if (u.hasRole('x_2203703_car_re_0.admin')) {
      data.staff = true;
      data.links.push({ label: 'Dashboard', id: 'admin_console' });
      data.links.push({ label: 'Desk', id: 'desk' });
    } else if (u.hasRole('x_2203703_car_re_0.receptionist')) {
      data.staff = true;
      data.links.push({ label: 'Desk', id: 'desk' });
      data.links.push({ label: 'My reservations', id: 'my_reservations' });
    }
  } catch (e) {
    gs.error('Staff Links: ' + e.message);
  }
})();
